   154→    for (let i = 0; i <= symbols.length - 3; i++) {
   155→      const pat = symbols.slice(i, i+3).join('');
   156→      patternCount[pat] = (patternCount[pat] || 0) + 1;
   157→      totalPatterns++;
   158→    }
   159→    
   160→    // 计算香农熵
   161→    let entropy = 0;
   162→    for (const key in patternCount) {
   163→      const p = patternCount[key] / totalPatterns;
   164→      if (p > 0) entropy -= p * Math.log2(p);
   165→    }
