   173→    
   174→    // VLF (<0.04Hz): 用极长窗口(25秒)移动平均代表极低频基线
   175→    const vlfWindow = 25;
   176→    const vlfBaseline = [];
   177→    for(let i=0; i<bpmSeq.length; i++) {
   178→      let sum = 0, count = 0;
   179→      for(let j=Math.max(0, i-vlfWindow); j<=Math.min(bpmSeq.length-1, i+vlfWindow); j++) {
   180→        sum += bpmSeq[j]; count++;
   181→      }
   182→      vlfBaseline.push(sum/count);
   183→    }
   184→    
   185→    // LF (0.04-0.15Hz): 用较短窗口(7秒)移动平均减去 VLF 基线
   186→    const lfWindow = 7;
   187→    const lfSignal = [];
   188→    for(let i=0; i<bpmSeq.length; i++) {
   189→      let sum = 0, count = 0;
   190→      for(let j=Math.max(0, i-lfWindow); j<=Math.min(bpmSeq.length-1, i+lfWindow); j++) {
