   274→// TCM 分段 SDNN + 心率稳定性
   275→function calcTcmMetrics(rr) {
   276→  if (!rr || rr.length < 2) return null;
   277→  const hrVals = rr.map(r => 60000 / r);
   278→  const hrMean = hrVals.reduce((a, b) => a + b, 0) / hrVals.length;
   279→  const hrStab = Math.sqrt(hrVals.reduce((s, v) => s + Math.pow(v - hrMean, 2), 0) / hrVals.length);
   280→  const segs = []; let acc = 0, srr = [];
   281→  for (let i = 0; i < rr.length; i++) {
   282→    acc += rr[i]; srr.push(rr[i]);
   283→    if (acc >= 60000 && srr.length >= 5) {
   284→      const sm = srr.reduce((a, b) => a + b, 0) / srr.length;
   285→      segs.push(+Math.sqrt(srr.reduce((s, r) => s + Math.pow(r - sm, 2), 0) / (srr.length - 1)).toFixed(2));
   286→      srr = []; acc = 0;
   287→    }
   288→  }
   289→  return { hrStability: +hrStab.toFixed(2), sdnnSegments: segs, rrCount: rr.length };
   290→}
