   292→// RSA: 从 BPM 序列提取 E/I ratio (呼吸-心率耦合指数)
   293→// 呼吸使心率周期性起伏（吸气升、呼气降）。去趋势后取局部峰=吸气相心率、
   294→// 谷=呼气相心率，E/I ≈ 平均峰值 / 平均谷值。峰谷用其在原序列的真实索引取回 BPM。
   295→function calcRsaEiRatio(bpmSeq) {
   296→  if (!bpmSeq || bpmSeq.length < 30) return 0;
   297→
   298→  // 去趋势：减去 ±5 窗口移动均值，保留呼吸尺度的波动
   299→  const detr = [];
   300→  for (let i = 0; i < bpmSeq.length; i++) {
   301→    let sum = 0, cnt = 0;
   302→    for (let j = Math.max(0, i - 5); j <= Math.min(bpmSeq.length - 1, i + 5); j++) { sum += bpmSeq[j]; cnt++; }
   303→    detr.push(bpmSeq[i] - sum / cnt);
   304→  }
   305→
   306→  // 在去趋势信号上找局部峰/谷，用真实索引取回对应 BPM
   307→  const peaks = [], troughs = [];
   308→  for (let i = 1; i < detr.length - 1; i++) {
   309→    if (detr[i] > detr[i - 1] && detr[i] >= detr[i + 1]) peaks.push(bpmSeq[i]);
   310→    else if (detr[i] < detr[i - 1] && detr[i] <= detr[i + 1]) troughs.push(bpmSeq[i]);
   311→  }
   312→  if (peaks.length < 2 || troughs.length < 2) return 0;
   313→
   314→  const avgPeak = peaks.reduce((a, b) => a + b, 0) / peaks.length;
   315→  const avgTrough = troughs.reduce((a, b) => a + b, 0) / troughs.length;
   316→  if (avgTrough <= 0) return 0;
   317→  return +(avgPeak / avgTrough).toFixed(3);
   318→}
